@@ -149,6 +149,25 @@ impl LineCellCache {
         }
     }

+    pub(crate) fn touches_bounds(&self, cells: &[(i64, i64)]) -> bool {
+        cells.iter().any(|&(x, y)| {
+            (x as f64 - 2.0) * GRID_SIZE <= self.bounds[0]
+                || (x as f64 + 2.0) * GRID_SIZE >= self.bounds[1]
+                || (y as f64 - 2.0) * GRID_SIZE <= self.bounds[2]
+                || (y as f64 + 2.0) * GRID_SIZE >= self.bounds[3]
+        })
+    }
+
+    pub(crate) fn rebuild_bounds(&mut self, grid: &FlatIntMap<Vec<LineRef>>) {
+        self.bounds = [f64::INFINITY, f64::NEG_INFINITY, f64::INFINITY, f64::NEG_INFINITY];
+        // Read actual grid entries: repeated ids can leave older geometry in
+        // other cells after the by-id map has been replaced. Whole footprints
+        // may widen the envelope but always cover every remaining entry.
+        for bucket in grid.values() {
+            for line in bucket { self.include_cells(line.cells()); }
+        }
+    }
