 mod tests {
     use super::*;

+    #[test]
+    fn bounds_shrink_with_grid_entries_including_repeated_ids() {
+        use crate::line::{build_line, push_line, remove_line};
+        let mut grid = FlatIntMap::default();
+        let mut cache = LineCellCache::default();
+        let old = build_line(7, 0.0, 0.0, 14.0, 0.0, 0, 0);
+        let replacement = build_line(7, 1400.0, 1400.0, 1414.0, 1400.0, 0, 0);
+        for line in [&old, &replacement] {
+            push_line(&mut grid, line, line.cells());
+            cache.include_cells(line.cells());
+        }
+        assert!(cache.touches_bounds(replacement.cells()));
+        assert!(!cache.touches_bounds(&[(50, 50)]));
+        let wide = cache.bounds;
+        // Removing the latest id leaves its older entry in another cell.
+        remove_line(&mut grid, replacement.id, replacement.cells());
