def uint(b,p):
 n=0;s=0
 while True:
  x=b[p];p+=1;n|=(x&127)<<s
  if x<128:return n,p
  s+=7
def string(b,p):
 n,p=uint(b,p);return b[p:p+n].decode(),p+n
def sections(b):
 p=8;ss=[]
 while p<len(b):
  k=b[p];n,p=uint(b,p+1);ss.append((k,b[p:p+n]));p+=n
 return ss
