import {readFileSync,writeFileSync} from 'node:fs';
import assert from 'node:assert/strict';
import {arcFeatureDistance} from '/home/holo/line/scripts/v0/optimizer/arc_value.ts';
const root='/tmp/engine-default-20261105';
let counts:any;
const weight=(k:number)=>k<7?2:k<47?1:4;
const distance=arcFeatureDistance;

type Node={lo:number[],hi:number[],ids?:number[],axis:number,split:number,left?:Node,right?:Node};
function build(rows:number[][],ids:number[]):Node{
 const n=rows[0].length,lo=Array(n).fill(Infinity),hi=Array(n).fill(-Infinity);
 for(const id of ids)for(let k=0;k<n;k++){const v=rows[id][k];if(v<lo[k])lo[k]=v;if(v>hi[k])hi[k]=v;}
 let axis=0;for(let k=1;k<n;k++)if((hi[k]-lo[k])**2*weight(k)>(hi[axis]-lo[axis])**2*weight(axis))axis=k;
 if(ids.length<=32)return{lo,hi,ids,axis,split:0};
 ids.sort((a,b)=>rows[a][axis]-rows[b][axis]||a-b);const mid=ids.length>>>1;
 return{lo,hi,axis,split:rows[ids[mid]][axis],left:build(rows,ids.slice(0,mid)),right:build(rows,ids.slice(mid))};
}
function bound(node:Node,q:number[],limit:number){
 let sum=0;
 for(let k=0;k<node.lo.length;k++){

  const d=q[k]<node.lo[k]?node.lo[k]-q[k]:q[k]>node.hi[k]?node.hi[k]-q[k]:0;
  if(d!==0){sum+=d*d*weight(k);if(sum>limit)return true;}
 }
 return false;
}
function page(model:number[][],locals:number[][],q:number[],size:number,tree?:Node){
 const rows=[...model,...locals],n=rows.length,k=Math.min(size,n),ds=new Float64Array(n),heap=new Uint32Array(k);
 const worse=(a:number,b:number)=>(ds[a]-ds[b]||a-b)>0;
 function sift(root:number){const value=heap[root];for(let child=root*2+1;child<k;child=root*2+1){if(child+1<k&&worse(heap[child+1],heap[child]))child++;if(!worse(heap[child],value))break;heap[root]=heap[child];root=child;}heap[root]=value;}
 for(let i=0;i<k;i++){ds[i]=distance(rows[i],q);heap[i]=i;}for(let i=(k>>>1)-1;i>=0;i--)sift(i);
 function visit(id:number){if(id<k)return;ds[id]=distance(rows[id],q,undefined,ds[heap[0]]);if(!worse(heap[0],id))return;heap[0]=id;sift(0);}
 function walk(node:Node){if(bound(node,q,ds[heap[0]])){return;}if(node.ids){for(const id of node.ids)visit(id);}else{
  if(q[node.axis]<node.split){walk(node.left!);walk(node.right!);}else{walk(node.right!);walk(node.left!);}
 }}
 if(tree){walk(tree);for(let i=Math.max(k,model.length);i<n;i++)visit(i);}else for(let i=k;i<n;i++)visit(i);
 return Array.from(heap).sort((a,b)=>ds[a]-ds[b]||a-b);
}
const empty=()=>({rows:0,terms:0,nodes:0,boundTerms:0,boundCoordinates:0,pruned:0});
for(const cell of [61,62]){
 const {models,queries}=JSON.parse(readFileSync(`${root}/queries-${cell}.json`,'utf8'));
 const start=performance.now(),trees=models.map((m:number[][])=>build(m,m.map((_,i)=>i)));const buildMs=performance.now()-start;
 const timings=[];
 for(let rep=0;rep<12;rep++){
  for(const indexed of (rep%2?[true,false]:[false,true])){
   const begin=performance.now();let checksum=0;
   for(const query of queries)for(const k of (query.pages??[32])){
    const result=page(models[query.model],query.locals,query.features,k,indexed?trees[query.model]:undefined);
    checksum+=result[0];
   }
   timings.push({rep,indexed,ms:performance.now()-begin,checksum});
  }
 }
 const result={cell,buildMs,timings};writeFileSync(`${root}/index-microbench-${cell}.json`,JSON.stringify(result,null,2)+'\n');console.log(result);
}

